<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { api, dateTime } from '../api'
import { inventoryKinds } from '../inventory'
import type { InventoryAlert, InventoryPage } from '../types'
const props=defineProps<{mode:string;revision:number}>(),emit=defineEmits<{count:[number];adjusted:[]}>()
const alerts=ref<InventoryAlert[]>([]),page=ref<InventoryPage>({items:[],total:0,limit:20,offset:0}),busy=ref(false),error=ref(''),onlyAlerts=ref(true)
const query=ref({skuId:'',kind:'',reference:'',startDate:'',endDate:''}),configuring=ref<InventoryAlert|null>(null),adjusting=ref<InventoryAlert|null>(null),stock=ref(0),reason=ref(''),saving=ref(false),formError=ref('')
const visibleAlerts=computed(()=>onlyAlerts.value?alerts.value.filter(a=>a.alert):alerts.value)
let request=0
async function load(offset=0){const current=++request;busy.value=true;error.value='';try{const result=await api<{items:InventoryAlert[]}>('admin.inventory.alerts');const movements=props.mode==='movements'?await api<InventoryPage>('admin.inventory.movements',{...query.value,offset,limit:20}):null;if(current!==request)return;alerts.value=result.items;emit('count',result.items.filter(a=>a.alert).length);if(movements)page.value=movements}catch(e){if(current===request)error.value=(e as Error).message}finally{if(current===request)busy.value=false}}
onMounted(()=>load());watch(()=>[props.mode,props.revision],()=>load())
function configure(row:InventoryAlert){configuring.value={...row};formError.value=''}
function adjust(row:InventoryAlert){adjusting.value={...row};stock.value=row.stock;reason.value='';formError.value=''}
async function save(){saving.value=true;formError.value='';try{if(configuring.value)await api('admin.inventory.alert.save',{skuId:configuring.value.skuId,threshold:configuring.value.threshold,enabled:configuring.value.enabled});else if(adjusting.value)await api('admin.inventory.batch',{items:[{skuId:adjusting.value.skuId,stock:stock.value,expectedStock:adjusting.value.stock}],reason:reason.value});configuring.value=null;adjusting.value=null;emit('adjusted');await load()}catch(e){formError.value=(e as Error).message}finally{saving.value=false}}
</script>

<template>
  <section class="panel inventory-panel">
    <div class="inventory-heading"><div><h3>{{mode==='movements'?'库存流水':'低库存告警'}}</h3><p>{{mode==='movements'?'仅记录功能启用后的服务内操作；不追溯历史，也不覆盖直接修改数据库的操作。云数据库仍需复验。':'已上架规格的可售库存 ≤ 阈值时告警，默认阈值 10，补货后自动解除。'}}</p></div><button class="button secondary" :disabled="busy" @click="load(page.offset)">刷新</button></div>
    <form v-if="mode==='movements'" class="inventory-filters" @submit.prevent="load()"><label>商品 / 规格<select v-model="query.skuId"><option value="">全部规格</option><option v-for="a in alerts" :key="a.skuId" :value="a.skuId">{{a.productName}} / {{a.skuName}}</option></select></label><label>变更类型<select v-model="query.kind"><option value="">全部类型</option><option v-for="(label,kind) in inventoryKinds" :key="kind" :value="kind">{{label}}</option></select></label><label>关联单号<input v-model.trim="query.reference" placeholder="订单号 / 商品编号"/></label><label>开始日期<input v-model="query.startDate" type="date"/></label><label>结束日期<input v-model="query.endDate" type="date"/></label><button class="button primary" :disabled="busy">查询</button><button type="button" class="button secondary" :disabled="busy" @click="query={skuId:'',kind:'',reference:'',startDate:'',endDate:''};load()">重置</button></form>
    <div v-else class="inventory-alert-summary"><strong class="inventory-warning">{{alerts.filter(a=>a.alert).length}} 个规格需要补货</strong><label><input v-model="onlyAlerts" type="checkbox"/> 仅查看告警规格</label></div>
    <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="busy" aria-live="polite">加载中…</p>
    <div v-else-if="mode==='movements'" class="inventory-table"><table><thead><tr><th>时间 / 操作人</th><th>商品 / 规格</th><th>类型 / 关联单号</th><th>可售库存</th><th>预占库存</th><th>已售数量</th><th>原因</th></tr></thead><tbody><tr v-for="m in page.items" :key="m.id"><td>{{dateTime(m.createdAt)}}<small class="block">{{m.username}}</small></td><td>{{m.productName}}<small class="block">{{m.skuName}}</small></td><td>{{inventoryKinds[m.kind]||m.kind}}<small class="block">{{m.reference||'—'}}</small></td><td>{{m.beforeStock}} → {{m.afterStock}}<small class="block" :class="m.afterStock<m.beforeStock?'inventory-warning':''">{{m.afterStock-m.beforeStock>0?'+':''}}{{m.afterStock-m.beforeStock}}</small></td><td>{{m.beforeReserved}} → {{m.afterReserved}}</td><td>{{m.beforeSold}} → {{m.afterSold}}</td><td>{{m.reason}}</td></tr><tr v-if="!page.items.length"><td colspan="7" class="inventory-empty">暂无库存流水</td></tr></tbody></table><div class="inventory-pagination"><span>共 {{page.total}} 条</span><button class="button secondary" :disabled="page.offset===0||busy" @click="load(page.offset-20)">上一页</button><span>第 {{Math.floor(page.offset/20)+1}} 页</span><button class="button secondary" :disabled="page.offset+20>=page.total||busy" @click="load(page.offset+20)">下一页</button></div></div>
    <div v-else class="inventory-table"><table><thead><tr><th>商品 / 规格</th><th>可售库存</th><th>预占库存</th><th>告警阈值</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in visibleAlerts" :key="a.skuId"><td>{{a.productName}}<small class="block">{{a.skuName}}</small></td><td><strong :class="a.alert?'inventory-warning':''">{{a.stock}}</strong></td><td>{{a.reserved}}</td><td>{{a.threshold}}</td><td><span :class="a.alert?'inventory-warning':''">{{!a.enabled?'已关闭':a.status!=='PUBLISHED'?'草稿（不告警）':a.stock===0?'已售罄':a.alert?'库存偏低':'库存充足'}}</span></td><td><button v-permission="'inventory.write'" class="text-button" @click="adjust(a)">调整库存</button><button v-permission="'inventory.write'" class="text-button" @click="configure(a)">设置阈值</button></td></tr><tr v-if="!visibleAlerts.length"><td colspan="6" class="inventory-empty">{{onlyAlerts?'暂无低库存告警':'暂无商品规格'}}</td></tr></tbody></table></div>
  </section>
  <div v-if="configuring||adjusting" class="modal-backdrop"><form class="drawer inventory-drawer" @submit.prevent="save"><div class="drawer-head"><h2>{{configuring?'低库存告警设置':'调整库存'}}</h2><button type="button" class="close" :disabled="saving" aria-label="关闭" @click="configuring=null;adjusting=null">×</button></div><div class="drawer-body form-grid"><p class="full">{{(configuring||adjusting)?.productName}} / {{(configuring||adjusting)?.skuName}}</p><template v-if="configuring"><label class="full">告警阈值<input v-model.number="configuring.threshold" type="number" min="0" max="2147483647" step="1" required/></label><label class="full">告警状态<select v-model="configuring.enabled"><option :value="true">开启</option><option :value="false">关闭</option></select></label></template><template v-else><p class="full">当前可售库存：{{adjusting?.stock}}，预占库存：{{adjusting?.reserved}}</p><label class="full">调整后可售库存<input v-model.number="stock" type="number" min="0" max="2147483647" step="1" required/></label><label class="full">调整原因<textarea v-model.trim="reason" maxlength="200" required/></label></template><p v-if="formError" class="form-error full" role="alert">{{formError}}</p></div><div class="drawer-foot"><button type="button" class="button secondary" :disabled="saving" @click="configuring=null;adjusting=null">取消</button><button v-permission="'inventory.write'" class="button primary" :disabled="saving">{{saving?'保存中…':'保存'}}</button></div></form></div>
</template>

<style scoped>
.inventory-panel{padding:24px;margin-bottom:24px}.inventory-heading,.inventory-alert-summary,.inventory-pagination{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px}.inventory-heading p{font-size:13px;color:#777;line-height:1.7;margin-top:8px}.inventory-filters{display:flex;flex-wrap:wrap;align-items:end;gap:12px;margin-bottom:20px}.inventory-filters label{display:grid;gap:8px;font-size:12px}.inventory-filters input,.inventory-filters select{padding:10px;border:1px solid var(--border);border-radius:8px;max-width:220px;background:var(--paper)}.inventory-warning{color:#b65221}.inventory-alert-summary label{font-size:13px;display:flex;align-items:center;gap:8px}.inventory-table{overflow-x:auto}.inventory-table table{min-width:760px}.inventory-table td{overflow-wrap:anywhere}.inventory-empty{text-align:center;padding:48px;color:#777}.inventory-pagination{justify-content:flex-end;margin-top:20px;margin-bottom:0;font-size:13px}.inventory-drawer{width:min(480px,100vw)}
</style>
